# Supplementary document: all substantive tables derive directly from CSV exports.
s=init('Supplementary methods and results for the Chattogram susceptibility revision')
para(s,'This supplement documents the actual spatial splits, calibration resampling, negative-subset experiments, coarse-predictor ablations and corrected uncertainty calculation. The underlying CSV files retain full precision and sample identifiers. Legacy area statistics are isolated as an audit record and are not presented as validation of the corrected uncertainty displays.')
heading(s,'S1 Spatial validation design')
fig(s,A/'figures/Figure_S1_spatial_clusters.png','Figure S1. Panel a shows the nine KMeans training clusters actually used for spatial CV, together with the 74 random holdout locations. Panel b shows a separate ten-cluster partition of all 369 records to address the requested all-sample display. Clustering uses geographic coordinates, n_init = 10 and seed 42. No vector study boundary was available for a reproducible overlay.')
para(s,'Table S1. GroupKFold assignments and class counts. The held-out training clusters do not include the 74-location random holdout.')
fold=pd.read_csv(A/'spatial_fold_counts.csv')
table(s,['Fold','Clusters','Train +','Train −','Test +','Test −','Test total'],fold[['Fold','Clusters','Train_positive','Train_negative','Test_positive','Test_negative','Test_n']].values.tolist())
para(s,'Table S2. Cluster composition and maximum separation among member points. Separations are great-circle distances using Earth radius 6,371,008.8 m, and do not define polygon widths.')
cs=pd.read_csv(A/'cluster_sizes.csv');table(s,['Cluster','Total','Positive','Negative','Maximum separation km'],[[r.Cluster,r.N,r.Positive,r.Negative,f'{r.Max_sample_separation_km:.2f}'] for r in cs.itertuples()])
fig(s,A/'figures/Figure_S2_validation.png','Figure S2. Comparison of repeated stratified CV means and reproduced spatial CV means. Repeated folds overlap and are not independent experimental replicates.')
heading(s,'S2 Calibration resampling')
para(s,'Each of 2,000 bootstrap replicates resamples 74 label–prediction pairs with replacement. Identical resampled indices are used for all models (NumPy default_rng seed 42). Models are not refitted. ECE uses positive-class empirical frequency, equal-width bins and zero contribution from empty bins. The GPC 10-bin interval excludes its point estimate because resampling increases the absolute bin discrepancies on average; it is a descriptive percentile interval, not a bias-corrected or spatial confidence guarantee. The paired GPC-minus-RF interval includes zero (−0.078 to 0.071).')
para(s,'Table S3. Holdout calibration bin occupancy. Entries are counts in probability bins [0,0.1], (0.1,0.2], …, (0.9,1]. Exact means and observed fractions are in calibration_bins.csv.')
bins=pd.read_csv(A/'calibration_bins.csv');table(s,['Model']+[str(i) for i in range(1,11)],[[n]+bins.query('Model==@n').N.tolist() for n in hold.index],[1.17]+[.54]*10)
para(s,'Table S4. ECE binning sensitivity and percentile bootstrap intervals. Bootstrap medians are distinct from original point estimates.')
table(s,['Model','Bins','Point ECE','Bootstrap median','95% interval'],[[r.Model,r.Bins,fmt(r.ECE),fmt(r.Bootstrap_median),f'{r.CI_low:.3f}–{r.CI_high:.3f}'] for r in boot.itertuples()])
heading(s,'S3 Negative subset sensitivity')
para(s,'For each seed we retain 136 of 171 original training negatives without replacement and all 124 training positives. The 74 holdout records remain fixed and are excluded from every training fit. Estimator seed 42 is held constant so the designated sensitivity seed changes the retained negative records. The experiment also changes the training prevalence. It does not create new negative locations, demonstrate stability of an unsampled domain or measure independent raster-map changes.')
para(s,'Table S5. Negative-subset sensitivity. The correlation and mean absolute error (MAE) compare predictions from each sensitivity fit with the corresponding baseline training fit at all 369 observed locations; this is a descriptive point-pattern comparison.')
table(s,['Seed','Model','AUC','MCC','ECE','Point ρ','Point MAE'],[[r.Seed,r.Model,fmt(r.ROC_AUC),fmt(r.MCC),fmt(r.ECE),fmt(r.All_points_Spearman),fmt(r.All_points_MAE)] for r in sens.itertuples()],[.45,1.15,.75,.75,.75,1.25,1.47])
heading(s,'S4 Coarse predictor ablations')
para(s,'Table S6. Excluding rainfall, soil, or both using the original split. No spatial detail is created by this analysis. The soil ablation also removes the questionable numeric soil-texture codes, so its effect is not solely a resolution effect.')
table(s,['Excluded','Model','AUC','MCC','Brier','ECE'],[[r.Analysis.replace('Without_','').replace('_',' '),r.Model,fmt(r.ROC_AUC),fmt(r.MCC),fmt(r.Brier),fmt(r.ECE)] for r in abl.itertuples()],[1.1,1.35,1,1,1,1.12])
heading(s,'S5 Conditional uncertainty and classification')
para(s,'The archived ambiguity score is reproduced by Uold = 1 − 2|p − 0.5| with a maximum absolute discrepancy of 2.78 × 10⁻¹⁶. It is not used as latent variance. The corrected output provides latent mean, latent variance, normalized latent standard deviation, probability-scale posterior variance and expected Bernoulli variance separately. Numerical quadrature verifies Var(q) + E[q(1 − q)] = E[q](1 − E[q]) to tolerance 10⁻¹². The kernel and normalization are conditional on the full-data fitted model and the 369-location display domain.')
para(s,'Table S7. Classification sensitivity at the observed locations. Fixed thirds are arbitrary comparison breaks, not calibrated decision thresholds. Agreement is the fraction of points assigned the same ordinal class as under tertiles.')
cl=pd.read_csv(A/'classification_sensitivity.csv');table(s,['Variable and method','Cuts','Low','Middle','High','Agreement'],[[r.Variable.replace('_',' ')+' / '+r.Method.replace('_',' '),f'{r.Lower_cut:.6f}\n{r.Upper_cut:.6f}',r.Low,r.Middle,r.High,f'{100*r.Agreement_with_tertiles:.1f}%'] for r in cl.itertuples()],[2.1,1.15,.65,.7,.65,1.32])
heading(s,'S6 SHAP specification')
para(s,'Kernel SHAP explains the positive-class logit of the GPC trained on the original 295 training records. The reference is 30 sampled training rows; all 74 holdout rows are explained, with 150 coalition evaluations per explanation, random seed 42 and SHAP 0.46.0. Background rows, explained rows and attribution arrays are archived. No conditional correction for feature dependence is applied. The input coding limitations documented in the manuscript remain relevant to the attributions.')
fig(s,A/'figures/Figure_S3_shap.png','Figure S3. Regenerated GPC Kernel SHAP summary on the positive-class log-odds scale. Color indicates the recorded predictor value, including numeric categorical codes. Attributions describe the fitted model and are not causal evidence.',6)
heading(s,'S7 Legacy SCAI audit record')
para(s,'Table S8. Preserved legacy SCAI values, included only to explain the withdrawn area claim. These values came from the full-data model and an interpolated 500 × 500 grid. They do not evaluate the corrected latent uncertainty, and their area denominator cannot be verified against a source polygon. The rows must not be cited as independent validation or percentages of the metropolitan area. The script selects five Jenks classes with a quantile fallback; the original numerical breakpoints were not saved in the CSV.')
legacy=pd.read_csv(ROOT/'results/data/SCAI_Analysis.csv');table(s,list(legacy.columns),[[fmt(v) if isinstance(v,float) else v for v in row] for row in legacy.values.tolist()])
