def comments(txt):
 blocks=[x.strip() for x in txt.splitlines() if x.strip()]
 return [x for x in blocks if x not in ['Comments to the Author'] and not x.startswith('I recommend major') and not x.startswith('The manuscript integrates Bayesian')]
